mapper.select:
/*selectMasterWmReReturnProgressStateList*/
SELECT
-- 발주정보 W.WMRE_NO -- 요청번호 ,W.PO_NO -- 발주번호 ,W.PO_SEQ -- 발주순번 ,D.PO_CREATE_DATE -- 발주일자 ,W.BUYER_ITEM_NO -- 품목코드 ,W.DESCRIPTION -- 품목명 ,W.SPECIFICATION -- 규격 ,W.ITEM_QTY -- 발주수량 ,W.UNIT_MEASURE -- 단위 ,(SELECT C.COM_NAME_LOC FROM ICOMCMPY C WHERE C.COM_CODE = W.SELLER) AS SELLER_NAME -- 협력사명
-- 고객사 요청정보 ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = W.BUYER AND CODE = W.BUYER_DEPT_CODE ) AS BUYER_DEPT_NAME -- 요청부서 ,W.BUYER_PERSON_NAME -- 요청자 ,W.PROCESS_TYPE ,(DECODE(W.PROCESS_TYPE,'0','직납','1','재고','2','TR','3','VMI')) PROCESS_TYPE_NM -- 출고구분 ,W.BUYER_PERSON_TEL ,W.B_REQ_DATE -- 요청일자 ,W.B_REQ_REMARK -- 요청사유(POP) ,W. WMRE_QTY -- 요청수량 ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM01' AND CODE = W.WMRE_TYPE ) AS WMRE_TYPE_NAME -- 요청구분(01반품/02교환 /03주문취소) ,W.WMRE_TYPE2 ,W.WMRE_TYPE3 ,W.WMRE_TYPE_DETAIL ,CASE WHEN W.WMRE_TYPE ='01' THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM02' AND CODE = W.WMRE_TYPE2 ) WHEN W.WMRE_TYPE ='02' THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM03' AND CODE = W.WMRE_TYPE2 ) ELSE '' END WMRE_TYPE2_NAME ,CASE WHEN W.WMRE_TYPE ='01' THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM04' AND CODE = W.WMRE_TYPE3 ) WHEN W.WMRE_TYPE ='02' THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM05' AND CODE = W.WMRE_TYPE3 ) ELSE '' END WMRE_TYPE3_NAME -- 운영사 접수정보 ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = W.ADD_USER_ID ) AS ADD_USER_NAME -- 접수자 , M_REC_DATE --접수일자 ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM07' AND CODE = W.FLAG ) AS FLAG_NAME -- 진행상태 , W.END_DATE --완료일자 , W.CANCEL_REMARK --취소사유(POP) ,W.S_REC_DATE ,W.S_PRT_DATE ,W.W_GR_DATE ,W.W_RIV_DATE ,W.S_GR_DATE ,W.W_CHGR_DATE ,W.W_CHDELI_DATE ,W.S_CHDELI_DATE ,W.CANCEL_DATE ,W.WMRE_FILE ,W.BUYER ,W.FLAG ,W.WMRE_TYPE ,( SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = F_GET_HIDDEN_BUYER_NAME(W.BUYER, '01') ) BUYER_NAME FROM BNTWMRE W, ICOMPOHD D
WHERE W.BUYER = D.BUYER(+) AND W.PO_NO = D.PO_NO(+) AND D.AGENT =#{st_com_code} AND W.WMRE_TYPE != '09'
AND W.M_REC_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND D.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND W.B_REQ_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND W.WMRE_NO LIKE #{st_WMRE_NO} || '%'
AND W.PO_NO LIKE #{st_PO_NO} || '%'
AND W.WMRE_TYPE = #{st_WMRE_TYPE}
AND W.FLAG = #{st_flag}
AND W.BUYER =#{st_buyer_code}
AND W.ADD_USER_NAME LIKE #{st_ADD_USER_NAME} || '%'
ORDER BY W.WMRE_NO DESC

/*getMasterWmReReturnProgressStateList_v2*/
SELECT X.* FROM ( SELECT
-- 발주정보 W.WMRE_NO -- 요청번호 ,W.PO_NO -- 발주번호 ,W.PO_SEQ -- 발주순번 ,D.PO_CREATE_DATE -- 발주일자 ,W.BUYER_ITEM_NO -- 품목코드 ,W.DESCRIPTION -- 품목명 ,W.SPECIFICATION -- 규격 ,W.ITEM_QTY -- 발주수량 ,W.UNIT_MEASURE -- 단위 ,(SELECT C.COM_NAME_LOC FROM ICOMCMPY C WHERE C.COM_CODE = W.SELLER) AS SELLER_NAME -- 협력사명
-- 고객사 요청정보 ,(SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = W.BUYER AND CODE = W.BUYER_DEPT_CODE ) AS BUYER_DEPT_NAME -- 요청부서 ,W.BUYER_PERSON_NAME -- 요청자 ,W.PROCESS_TYPE ,(DECODE(W.PROCESS_TYPE,'0','직납','1','재고','2','TR','3','VMI')) PROCESS_TYPE_NM -- 출고구분 ,W.BUYER_PERSON_TEL ,W.B_REQ_DATE -- 요청일자 ,W.B_REQ_REMARK -- 요청사유(POP) ,W. WMRE_QTY -- 요청수량 ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM01' AND CODE = W.WMRE_TYPE ) AS WMRE_TYPE_NAME -- 요청구분(01반품/02교환 /03주문취소) ,W.WMRE_TYPE2 ,W.WMRE_TYPE3 ,W.WMRE_TYPE_DETAIL ,CASE WHEN W.WMRE_TYPE ='01' THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM02' AND CODE = W.WMRE_TYPE2 ) WHEN W.WMRE_TYPE ='02' THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM03' AND CODE = W.WMRE_TYPE2 ) ELSE '' END WMRE_TYPE2_NAME ,CASE WHEN W.WMRE_TYPE ='01' THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM04' AND CODE = W.WMRE_TYPE3 ) WHEN W.WMRE_TYPE ='02' THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM05' AND CODE = W.WMRE_TYPE3 ) ELSE '' END WMRE_TYPE3_NAME -- 운영사 접수정보 ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = W.ADD_USER_ID ) AS ADD_USER_NAME -- 접수자 , M_REC_DATE --접수일자 ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'WM07' AND CODE = W.FLAG ) AS FLAG_NAME -- 진행상태 , W.END_DATE --완료일자 , W.CANCEL_REMARK --취소사유(POP) ,W.S_REC_DATE ,W.S_PRT_DATE ,W.W_GR_DATE ,W.W_RIV_DATE ,W.S_GR_DATE ,W.W_CHGR_DATE ,W.W_CHDELI_DATE ,W.S_CHDELI_DATE ,W.CANCEL_DATE ,W.WMRE_FILE ,W.BUYER ,W.FLAG ,W.WMRE_TYPE ,( SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = F_GET_HIDDEN_BUYER_NAME(W.BUYER, '01') ) BUYER_NAME ,DECODE(W.S_REC_DATE,NULL,'/resources/imgs/Btn_RegIng.gif','/resources/imgs/Btn_RegEnd.gif') AS REC_STATUS_BUTTON ,DECODE(W.S_GR_DATE,NULL,'/resources/imgs/Btn_RegIng.gif','/resources/imgs/Btn_RegEnd.gif') AS GR_STATUS_BUTTON FROM BNTWMRE W, ICOMPOHD D
WHERE W.BUYER = D.BUYER(+) AND W.PO_NO = D.PO_NO(+) AND D.AGENT =#{st_com_code} AND W.WMRE_TYPE != '09' AND W.B_REQ_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND W.WMRE_NO LIKE UPPER('%'||#{st_wmre_no} || '%')
AND W.PO_NO IN
UPPER(#{item})
AND W.BUYER_ITEM_NO LIKE UPPER('%'||TRIM(#{st_buyer_item_no})||'%')
AND W.DESCRIPTION LIKE '%'||TRIM(#{st_description})||'%'
AND W.WMRE_TYPE = #{st_wmre_type}
AND W.FLAG = #{st_flag}
AND W.BUYER =#{st_buyer_code}
ORDER BY W.WMRE_NO DESC )X WHERE 1=1
AND REPLACE(UPPER(X.BUYER_NAME),' ','') LIKE '%'||UPPER(TRIM(REPLACE(#{st_buyer_name},' ','')))||'%'
